def find_common_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def timeToMinutes(text):
        if isinstance(text, int):
            return text
        if not isinstance(text, str):
            return None
        text = text.strip()
        parts = text.split(":")
        if len(parts) != 2:
            return None
        try:
            hour = int(parts[0])
            minute = int(parts[1])
        except Exception:
            return None
        if hour < 0 or hour > 23 or minute < 0 or minute > 59:
            return None
        return hour * 60 + minute

    def minutesToTime(value):
        hour = value // 60
        minute = value % 60
        if hour < 10:
            hourText = "0" + str(hour)
        else:
            hourText = str(hour)
        if minute < 10:
            minuteText = "0" + str(minute)
        else:
            minuteText = str(minute)
        return hourText + ":" + minuteText

    def parseIntervalObject(obj):
        if isinstance(obj, dict):
            startValue = None
            endValue = None
            startKeys = ["start", "from", "begin", "open"]
            endKeys = ["end", "to", "finish", "until", "close"]
            for key in startKeys:
                if key in obj:
                    startValue = timeToMinutes(obj[key])
                    break
            for key in endKeys:
                if key in obj:
                    endValue = timeToMinutes(obj[key])
                    break
            if startValue is not None and endValue is not None:
                return [startValue, endValue]
        if isinstance(obj, str):
            text = obj.strip()
            if "-" in text:
                parts = text.split("-")
                if len(parts) == 2:
                    startValue = timeToMinutes(parts[0].strip())
                    endValue = timeToMinutes(parts[1].strip())
                    if startValue is not None and endValue is not None:
                        return [startValue, endValue]
        if isinstance(obj, list) or isinstance(obj, tuple):
            if len(obj) == 2:
                startValue = timeToMinutes(obj[0])
                endValue = timeToMinutes(obj[1])
                if startValue is not None and endValue is not None:
                    return [startValue, endValue]
        return None

    def collectIntervals(obj, intervals):
        interval = parseIntervalObject(obj)
        if interval is not None:
            intervals.append(interval)
            return
        if isinstance(obj, dict):
            for value in obj.values():
                collectIntervals(value, intervals)
        elif isinstance(obj, list) or isinstance(obj, tuple):
            for item in obj:
                collectIntervals(item, intervals)

    def mergeIntervals(intervals):
        cleaned = []
        for interval in intervals:
            if len(interval) != 2:
                continue
            startValue = interval[0]
            endValue = interval[1]
            if startValue is None or endValue is None:
                continue
            if startValue < 0:
                startValue = 0
            if endValue > 1440:
                endValue = 1440
            if endValue < 0:
                endValue = 0
            if startValue > 1440:
                startValue = 1440
            if endValue > startValue:
                cleaned.append([startValue, endValue])
        cleaned = sorted(cleaned, key=lambda item: (item[0], item[1]))
        merged = []
        for interval in cleaned:
            if len(merged) == 0 or interval[0] > merged[-1][1]:
                merged.append([interval[0], interval[1]])
            else:
                if interval[1] > merged[-1][1]:
                    merged[-1][1] = interval[1]
        return merged

    def hasWorkKey(obj):
        if not isinstance(obj, dict):
            return False
        workKeys = ["working_hours", "workingHours", "work_hours", "workHours", "hours", "availability"]
        for key in workKeys:
            if key in obj:
                return True
        return False

    def getWorkIntervals(data):
        workKeys = ["working_hours", "workingHours", "work_hours", "workHours", "hours", "availability"]
        if isinstance(data, dict):
            for key in workKeys:
                if key in data:
                    intervals = []
                    collectIntervals(data[key], intervals)
                    if len(intervals) > 0:
                        return intervals
        return []

    def getBusyIntervals(data):
        busy = []
        busyKeys = ["busy", "events", "calendar", "appointments", "meetings", "schedule"]
        if isinstance(data, dict):
            foundBusyKey = False
            for key in busyKeys:
                if key in data:
                    foundBusyKey = True
                    collectIntervals(data[key], busy)
            if not foundBusyKey:
                directInterval = parseIntervalObject(data)
                if directInterval is not None and not hasWorkKey(data):
                    busy.append(directInterval)
                else:
                    workKeys = ["working_hours", "workingHours", "work_hours", "workHours", "hours", "availability"]
                    for key, value in data.items():
                        if key not in workKeys:
                            collectIntervals(value, busy)
        elif isinstance(data, list) or isinstance(data, tuple):
            collectIntervals(data, busy)
        return busy

    earliestMinutes = 0
    if earliest != "":
        parsedEarliest = timeToMinutes(earliest)
        if parsedEarliest is not None:
            earliestMinutes = parsedEarliest

    latestMinutes = 1440
    if latest_end != "":
        parsedLatest = timeToMinutes(latest_end)
        if parsedLatest is not None:
            latestMinutes = parsedLatest

    if len(days) == 0:
        return {"starts": []}

    people = [""]
    for person in attendees:
        people.append(person)

    commonStarts = None
    dayMaxStart = 23 * 60 + 45

    for day in days:
        dayStarts = set()
        for person in people:
            calendarData = api.read_calendar(person, day)
            workIntervals = getWorkIntervals(calendarData)
            if len(workIntervals) == 0:
                workIntervals = [[0, 1440]]
            busyIntervals = mergeIntervals(getBusyIntervals(calendarData))
            workIntervals = mergeIntervals(workIntervals)

            freeIntervals = []
            for workInterval in workIntervals:
                cursor = workInterval[0]
                for busyInterval in busyIntervals:
                    if busyInterval[1] <= cursor:
                        continue
                    if busyInterval[0] >= workInterval[1]:
                        break
                    if busyInterval[0] > cursor:
                        freeIntervals.append([cursor, min(busyInterval[0], workInterval[1])])
                    if busyInterval[1] > cursor:
                        cursor = busyInterval[1]
                    if cursor >= workInterval[1]:
                        break
                if cursor < workInterval[1]:
                    freeIntervals.append([cursor, workInterval[1]])

            personStarts = set()
            for freeInterval in freeIntervals:
                leftBound = freeInterval[0]
                rightBound = freeInterval[1]
                if leftBound < earliestMinutes:
                    leftBound = earliestMinutes
                if rightBound > latestMinutes:
                    rightBound = latestMinutes
                latestStart = rightBound - minutes
                if latestStart > dayMaxStart:
                    latestStart = dayMaxStart
                if leftBound < 0:
                    leftBound = 0
                firstStart = ((leftBound + 14) // 15) * 15
                if firstStart > dayMaxStart:
                    continue
                if latestStart < firstStart:
                    continue
                for startValue in range(firstStart, latestStart + 1, 15):
                    if startValue >= 0 and startValue <= dayMaxStart:
                        personStarts.add(startValue)

            if commonStarts is None:
                commonStarts = personStarts
            else:
                commonStarts = commonStarts.intersection(personStarts)

            if len(commonStarts) == 0:
                break

        if commonStarts is None:
            commonStarts = set()
        if len(commonStarts) == 0:
            break

    starts = sorted(commonStarts)
    return {"starts": [minutesToTime(value) for value in starts]}
