def find_common_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def to_minutes(text):
        if text == "":
            return None
        parts = text.split(":")
        if len(parts) != 2:
            raise ValueError("bad time")
        return int(parts[0]) * 60 + int(parts[1])

    def to_time(total):
        h = total // 60
        m = total % 60
        hh = str(h)
        mm = str(m)
        if len(hh) == 1:
            hh = "0" + hh
        if len(mm) == 1:
            mm = "0" + mm
        return hh + ":" + mm

    def ceil_quarter(total):
        r = total % 15
        if r == 0:
            return total
        return total + (15 - r)

    intervals = []

    def add_interval(start_text, end_text, obj):
        try:
            start = to_minutes(start_text)
            end = to_minutes(end_text)
        except Exception:
            return
        if start is None or end is None:
            return
        status = ""
        if isinstance(obj, dict):
            if "status" in obj:
                status = str(obj["status"]).lower()
            elif "availability" in obj:
                status = str(obj["availability"]).lower()
            elif "transparency" in obj:
                status = str(obj["transparency"]).lower()
        if "free" in status or "available" in status or "transparent" in status:
            return
        if end > start:
            intervals.append((start, end))

    def collect(obj):
        if obj is None:
            return
        if isinstance(obj, dict):
            if "start" in obj and "end" in obj:
                add_interval(obj["start"], obj["end"], obj)
                return
            if "from" in obj and "to" in obj:
                add_interval(obj["from"], obj["to"], obj)
                return
            if "begin" in obj and "end" in obj:
                add_interval(obj["begin"], obj["end"], obj)
                return
            if "start_time" in obj and "end_time" in obj:
                add_interval(obj["start_time"], obj["end_time"], obj)
                return

            keys = [
                "busy",
                "events",
                "calendar",
                "calendars",
                "items",
                "slots",
                "meetings",
                "intervals",
            ]
            found = False
            for key in keys:
                if key in obj:
                    collect(obj[key])
                    found = True
            if not found:
                if len(obj) == 2:
                    vals = list(obj.values())
                    if isinstance(vals[0], str) and isinstance(vals[1], str):
                        if ":" in vals[0] and ":" in vals[1]:
                            add_interval(vals[0], vals[1], obj)
                            return
        elif isinstance(obj, list) or isinstance(obj, tuple):
            if len(obj) == 2 and isinstance(obj[0], str) and isinstance(obj[1], str):
                if ":" in obj[0] and ":" in obj[1]:
                    add_interval(obj[0], obj[1], obj)
                    return
            for item in obj:
                collect(item)
        elif isinstance(obj, str):
            text = obj.strip()
            pos = text.find("-")
            if pos != -1:
                left = text[:pos].strip()
                right = text[pos + 1:].strip()
                if ":" in left and ":" in right:
                    add_interval(left, right, obj)

    if earliest == "":
        low = 0
    else:
        low = to_minutes(earliest)
    if latest_end == "":
        high_end = 24 * 60
    else:
        high_end = to_minutes(latest_end)

    first_start = ceil_quarter(low)
    last_start = high_end - minutes

    if first_start > last_start:
        return {"starts": []}

    candidates = []
    start = first_start
    while start <= last_start:
        candidates.append(start)
        start += 15

    for day in days:
        day_intervals = []
        intervals = []
        cal = api.read_calendar("", day)
        collect(cal)
        for person in attendees:
            cal = api.read_calendar(person, day)
            collect(cal)
        day_intervals = intervals

        next_candidates = []
        for start in candidates:
            end = start + minutes
            ok = True
            for busy_start, busy_end in day_intervals:
                if start < busy_end and end > busy_start:
                    ok = False
                    break
            if ok:
                next_candidates.append(start)
        candidates = next_candidates
        if not candidates:
            break

    starts = []
    for start in candidates:
        starts.append(to_time(start))
    return {"starts": starts}
