def find_common_starts(api, attendees, days, minutes, earliest="", latest_end=""):
    def parse_time(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def format_time(total):
        return str(total // 60).zfill(2) + ":" + str(total % 60).zfill(2)

    def parse_offset(text):
        sign = 1
        if text and text[0] == "-":
            sign = -1
            text = text[1:]
        elif text and text[0] == "+":
            text = text[1:]
        parts = text.split(":")
        return sign * (int(parts[0]) * 60 + int(parts[1]))

    def clip_interval(start, end):
        if end <= 0 or start >= 1440:
            return []
        if start < 0:
            start = 0
        if end > 1440:
            end = 1440
        if start >= end:
            return []
        return [start, end]

    def collect_calendar_data(cal, user_offset):
        person_offset = parse_offset(cal["utc_offset"])
        delta = user_offset - person_offset

        work_parts = cal["working_hours"].split("-")
        work_start = parse_time(work_parts[0]) + delta
        work_end = parse_time(work_parts[1]) + delta
        work_window = clip_interval(work_start, work_end)

        buffer = 15
        note = cal.get("note", "")
        if not note or "15 minutes" not in note:
            buffer = 0

        busy = []
        for day_info in cal.get("days", []):
            for event in day_info.get("events", []):
                if event.get("show_as") == "busy":
                    start = parse_time(event["start"]) - buffer
                    end = parse_time(event["end"]) + buffer
                    interval = clip_interval(start + delta, end + delta)
                    if interval:
                        busy.append(interval)

        return work_window, busy

    start_min = 0
    if earliest:
        start_min = ((parse_time(earliest) + 14) // 15) * 15

    start_max = 1440 - minutes
    if latest_end:
        start_max = min(start_max, parse_time(latest_end) - minutes)

    if start_max < start_min:
        return {"starts": []}

    common = None

    for day in days:
        user_calendar = api.read_calendar("", day)
        user_offset = parse_offset(user_calendar["utc_offset"])

        people = [user_calendar]
        for name in attendees:
            people.append(api.read_calendar(name, day))

        day_data = []
        for cal in people:
            day_data.append(collect_calendar_data(cal, user_offset))

        allowed = []
        for start in range(start_min, start_max + 1, 15):
            end = start + minutes
            if end > 1440:
                continue
            ok = True
            for work_window, busy in day_data:
                if not work_window:
                    ok = False
                    break
                if start < work_window[0] or end > work_window[1]:
                    ok = False
                    break
                for interval in busy:
                    if start < interval[1] and interval[0] < end:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                allowed.append(start)

        if common is None:
            common = allowed
        else:
            allowed_set = set(allowed)
            common = [x for x in common if x in allowed_set]

        if not common:
            return {"starts": []}

    return {"starts": [format_time(x) for x in common] if common else []}
