def find_common_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def time_to_minutes(text):
        return int(text[0:2]) * 60 + int(text[3:5])

    def minutes_to_time(total):
        return str(total // 60).zfill(2) + ":" + str(total % 60).zfill(2)

    def parse_offset(text):
        sign = -1 if text and text[0] == "-" else 1
        return sign * (int(text[1:3]) * 60 + int(text[4:6]))

    def ceil_quarter(total):
        rem = total % 15
        if rem == 0:
            return total
        return total + (15 - rem)

    def note_buffer(note):
        if not note:
            return 0
        digits = ""
        for ch in note:
            if ch.isdigit():
                digits += ch
            elif digits:
                break
        if digits:
            return int(digits)
        return 0

    def norm_day(day):
        if not day:
            return day
        return day[:1].upper() + day[1:].lower()

    def get_day_info(cal, wanted):
        target = wanted.lower()
        for item in cal.get("days", []):
            if item.get("day", "").lower() == target:
                return item
        if cal.get("days", []):
            return cal["days"][0]
        return {"events": []}

    cache = {}

    def get_calendar(person, day):
        key = (person, day)
        if key not in cache:
            cache[key] = api.read_calendar(person, day)
        return cache[key]

    earliest_min = time_to_minutes(earliest) if earliest else 0
    earliest_min = ceil_quarter(earliest_min)
    latest_min = time_to_minutes(latest_end) if latest_end else 24 * 60

    daily = []
    for day in days:
        d = norm_day(day)

        user_cal = get_calendar("", d)
        user_offset = parse_offset(user_cal.get("utc_offset", "+00:00"))
        user_info = get_day_info(user_cal, d)

        user_wh = user_cal.get("working_hours", "00:00-24:00").split("-")
        user_start = time_to_minutes(user_wh[0])
        user_end = time_to_minutes(user_wh[1])

        user_gap = note_buffer(user_cal.get("note", ""))
        user_blocked = []
        for event in user_info.get("events", []):
            if event.get("show_as", "busy") == "busy":
                bs = time_to_minutes(event.get("start", "00:00")) - user_gap
                be = time_to_minutes(event.get("end", "00:00")) + user_gap
                user_blocked.append((bs, be))

        people = []
        for person in attendees:
            cal = get_calendar(person, d)
            person_offset = parse_offset(cal.get("utc_offset", "+00:00"))
            delta = user_offset - person_offset
            info = get_day_info(cal, d)

            wh = cal.get("working_hours", "00:00-24:00").split("-")
            start = time_to_minutes(wh[0]) + delta
            end = time_to_minutes(wh[1]) + delta

            gap = note_buffer(cal.get("note", ""))
            blocked = []
            for event in info.get("events", []):
                if event.get("show_as", "busy") == "busy":
                    bs = time_to_minutes(event.get("start", "00:00")) + delta - gap
                    be = time_to_minutes(event.get("end", "00:00")) + delta + gap
                    blocked.append((bs, be))

            people.append((start, end, blocked))

        daily.append((user_start, user_end, user_blocked, people))

    starts = []
    if latest_min < earliest_min:
        return {"starts": starts}

    for start in range(earliest_min, latest_min - minutes + 1, 15):
        end = start + minutes
        if end > latest_min:
            continue

        ok = True
        for user_start, user_end, user_blocked, people in daily:
            if start < user_start or end > user_end:
                ok = False
                break

            for bs, be in user_blocked:
                if start < be and end > bs:
                    ok = False
                    break
            if not ok:
                break

            for person_start, person_end, blocked in people:
                if start < person_start or end > person_end:
                    ok = False
                    break

                for bs, be in blocked:
                    if start < be and end > bs:
                        ok = False
                        break
                if not ok:
                    break

            if not ok:
                break

        if ok:
            starts.append(minutes_to_time(start))

    return {"starts": starts}
