def find_common_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parse_time(text):
        return int(text[0:2]) * 60 + int(text[3:5])

    def format_time(value):
        value = value % (24 * 60)
        return str(value // 60).zfill(2) + ":" + str(value % 60).zfill(2)

    def parse_offset(text):
        sign = 1
        if text[0] == "-":
            sign = -1
        return sign * (int(text[1:3]) * 60 + int(text[4:6]))

    def ceil_quarter(value):
        r = value % 15
        if r == 0:
            return value
        return value + (15 - r)

    def dayrecord(data, day):
        code = day[0:3].lower()
        items = data.get("days", [])
        for item in items:
            if item.get("day", "") == code:
                return item
        if len(items) > 0:
            return items[0]
        return {}

    def collect(data, user_off, day):
        shift = user_off - parse_offset(data["utc_offset"])
        record = dayrecord(data, day)
        wh = data.get("working_hours", "00:00-23:59")
        start = parse_time(wh[0:5]) + shift
        end = parse_time(wh[6:11]) + shift
        buffer = 15 if "note" in data and "15 minutes" in data["note"] else 0
        busy = []
        for event in record.get("events", []):
            if event.get("show_as", "") == "busy":
                busy.append((
                    parse_time(event["start"]) + shift - buffer,
                    parse_time(event["end"]) + shift + buffer
                ))
        return start, end, busy

    common = None
    for day in days:
        user_data = api.read_calendar("", day)
        user_off = parse_offset(user_data["utc_offset"])
        user_start, user_end, user_busy = collect(user_data, user_off, day)

        lower = user_start
        upper = user_end - minutes

        if earliest != "":
            lower = max(lower, ceil_quarter(parse_time(earliest)))
        if latest_end != "":
            upper = min(upper, parse_time(latest_end) - minutes)

        lower = max(lower, 0)
        upper = min(upper, 24 * 60 - minutes)

        busy = list(user_busy)

        for person in attendees:
            data = api.read_calendar(person, day)
            person_start, person_end, person_busy = collect(data, user_off, day)
            lower = max(lower, person_start)
            upper = min(upper, person_end - minutes)
            busy.extend(person_busy)

        lower = max(lower, 0)
        upper = min(upper, 24 * 60 - minutes)

        valid = set()
        if upper >= lower:
            start = ceil_quarter(lower)
            while start <= upper:
                end = start + minutes
                ok = True
                for s, e in busy:
                    if not (end <= s or start >= e):
                        ok = False
                        break
                if ok:
                    valid.add(start)
                start += 15

        if common is None:
            common = valid
        else:
            common = common.intersection(valid)

    if common is None:
        common = set()

    return {"starts": [format_time(x) for x in sorted(common)]}
