def find_common_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parse_minutes(t):
        return int(t[0:2]) * 60 + int(t[3:5])

    def parse_offset(o):
        if not o:
            return 0
        sign = -1 if o[0] == "-" else 1
        return sign * (int(o[1:3]) * 60 + int(o[4:6]))

    def format_minutes(m):
        h, mm = divmod(m, 60)
        hs = str(h)
        ms = str(mm)
        if h < 10:
            hs = "0" + hs
        if mm < 10:
            ms = "0" + ms
        return hs + ":" + ms

    def add_interval(intervals, start, end):
        while start < 0:
            start += 1440
            end += 1440
        while start >= 1440:
            start -= 1440
            end -= 1440
        if end <= start:
            intervals.append((start, 1440))
            intervals.append((0, end))
        elif end <= 1440:
            intervals.append((start, end))
        else:
            intervals.append((start, 1440))
            intervals.append((0, end - 1440))

    def convert_interval(intervals, start_txt, end_txt, user_off, person_off):
        if not start_txt or not end_txt:
            return
        start = parse_minutes(start_txt)
        end = parse_minutes(end_txt)
        if end < start:
            end += 1440
        start = start + user_off - person_off
        end = end + user_off - person_off
        add_interval(intervals, start, end)

    def merge_intervals(intervals):
        items = sorted(intervals)
        merged = []
        for start, end in items:
            if end <= start:
                continue
            if not merged or start > merged[-1][1]:
                merged.append([start, end])
            elif end > merged[-1][1]:
                merged[-1][1] = end
        return [(a, b) for a, b in merged]

    def build_person(info, user_off):
        person_off = parse_offset(info.get("utc_offset", ""))
        work = []
        busy = []

        wh = info.get("working_hours", "")
        if wh and "-" in wh:
            parts = wh.split("-")
            if len(parts) == 2:
                convert_interval(work, parts[0], parts[1], user_off, person_off)
        if not work:
            work.append((0, 1440))
        work = merge_intervals(work)

        days_info = info.get("days", [])
        day_info = days_info[0] if len(days_info) > 0 else {}
        events = day_info.get("events", [])
        for ev in events:
            if ev.get("show_as") != "free":
                convert_interval(
                    busy,
                    ev.get("start", ""),
                    ev.get("end", ""),
                    user_off,
                    person_off,
                )
        busy = merge_intervals(busy)
        return work, busy

    def allowed_on_day(work, busy, start_min):
        end_min = start_min + minutes
        if end_min > 1440:
            return False
        if not any(start_min >= a and end_min <= b for a, b in work):
            return False
        if any(not (end_min <= a or start_min >= b) for a, b in busy):
            return False
        return True

    earliest_min = parse_minutes(earliest) if earliest else 0
    latest_limit = parse_minutes(latest_end) if latest_end else 1440

    first_start = ((earliest_min + 14) // 15) * 15
    last_start = latest_limit - minutes
    if last_start > 1439:
        last_start = 1439
    last_start = (last_start // 15) * 15

    common = None

    for day in days:
        user_info = api.read_calendar("", day)
        user_off = parse_offset(user_info.get("utc_offset", ""))

        people = []
        people.append(build_person(user_info, user_off))

        seen = set()
        for name in attendees:
            if name not in seen:
                seen.add(name)
                info = api.read_calendar(name, day)
                people.append(build_person(info, user_off))

        day_starts = set()
        if last_start >= first_start:
            for start_min in range(first_start, last_start + 1, 15):
                ok = True
                for work, busy in people:
                    if not allowed_on_day(work, busy, start_min):
                        ok = False
                        break
                if ok:
                    day_starts.add(start_min)

        if common is None:
            common = day_starts
        else:
            common = common.intersection(day_starts)

    if common is None:
        common = set()

    return {"starts": [format_minutes(m) for m in sorted(common)]}
