        hour = total // 60
        minute = total % 60
        return str(hour).zfill(2) + ":" + str(minute).zfill(2)

    def parseOffset(text):
        sign = 1
        if text[0] == "-":
            sign = -1
        parts = text[1:].split(":")
        return sign * (int(parts[0]) * 60 + int(parts[1]))

    def parseBuffer(calendar):
        note = ""
        if "note" in calendar:
            note = calendar["note"]
        num = ""
        for ch in note:
            if ch.isdigit():
                num += ch
            elif num != "":
                break
        if num == "":
            return 0
        return int(num)

    def parseWorking(calendar):
        text = calendar["working_hours"]
        parts = text.split("-")
        return toMinutes(parts[0]), toMinutes(parts[1])

    def fitsCalendar(calendar, userOffset, start, length, personOffset, buffer):
        localStart = start + personOffset - userOffset
        localEnd = localStart + length

        if localStart < 0 or localEnd > 24 * 60:
            return False

        workStart, workEnd = parseWorking(calendar)
        if localStart < workStart or localEnd > workEnd:
            return False

        daysData = calendar.get("days", [])
        events = []
        if len(daysData) > 0:
            events = daysData[0].get("events", [])

        for event in events:
            if event.get("show_as", "busy") != "busy":
                continue
            eventStart = toMinutes(event["start"]) - buffer
            eventEnd = toMinutes(event["end"]) + buffer
            if localStart < eventEnd and localEnd > eventStart:
                return False

        return True

    if len(days) == 0:
        return {"starts": []}

    calendars = {}
    userOffsets = {}
    for day in days:
        calendars[day] = {}
        userCalendar = api.read_calendar("", day)
        calendars[day][""] = userCalendar
        userOffsets[day] = parseOffset(userCalendar["utc_offset"])
        for person in attendees:
            calendars[day][person] = api.read_calendar(person, day)

    earliestMin = 0
    if earliest != "":
        earliestMin = toMinutes(earliest)

    latestMin = 24 * 60
    if latest_end != "":
        latestMin = toMinutes(latest_end)

    starts = []
    for start in range(0, 24 * 60, 15):
        if start < earliestMin:
            continue
        if start + minutes > latestMin:
            continue

        ok = True
        for day in days:
            userCalendar = calendars[day][""]
            userOffset = userOffsets[day]

            if not fitsCalendar(userCalendar, userOffset, start, minutes, userOffset, 0):
                ok = False
                break

            for person in attendees:
                personCalendar = calendars[day][person]
                personOffset = parseOffset(personCalendar["utc_offset"])
                buffer = parseBuffer(personCalendar)
                if not fitsCalendar(personCalendar, userOffset, start, minutes, personOffset, buffer):
                    ok = False
                    break

            if not ok:
                break

        if ok:
            starts.append(toTime(start))

    return {"starts": starts}
