    def parse_time(t):
        t = str(t)
        if len(t) < 5:
            return 0
        return int(t[0:2]) * 60 + int(t[3:5])

    def fmt_time(m):
        m = m % 1440
        return str(m // 60).zfill(2) + ":" + str(m % 60).zfill(2)

    def parse_offset(s):
        s = str(s)
        if not s:
            return 0
        sign = -1 if s[0] == "-" else 1
        return sign * (int(s[1:3]) * 60 + int(s[4:6]))

    def get_day_item(resp, day):
        items = resp.get("days", [])
        want = str(day).lower()[:3]
        for item in items:
            d = str(item.get("day", "")).lower()
            if d == str(day).lower() or d.startswith(want):
                return item
        return items[0] if items else {}

    def first_number(text):
        text = str(text)
        digits = ""
        started = False
        for ch in text:
            if ch.isdigit():
                digits += ch
                started = True
            elif started:
                break
        return int(digits) if digits else 0

    def convert_interval(start, end, delta):
        s = start + delta
        e = end + delta
        res = []
        if e <= s:
            if s < 1440:
                res.append((max(0, s), 1440))
            if e > 0:
                res.append((0, min(1440, e)))
            return res
        if e <= 0 or s >= 1440:
            return res
        res.append((max(0, s), min(1440, e)))
        return res

    def merge_intervals(intervals):
        if not intervals:
            return []
        items = sorted(intervals)
        merged = [[items[0][0], items[0][1]]]
        for a, b in items[1:]:
            if a <= merged[-1][1]:
                if b > merged[-1][1]:
                    merged[-1][1] = b
            else:
                merged.append([a, b])
        return [(a, b) for a, b in merged]

    if not days:
        return {"starts": []}

    start_bound = parse_time(earliest) if earliest else 0
    if latest_end:
        end_bound = parse_time(latest_end) - minutes
    else:
        end_bound = 1440 - minutes

    first_start = ((start_bound + 14) // 15) * 15
    last_start = (end_bound // 15) * 15

    if last_start < first_start:
        return {"starts": []}

    day_blocks = []

    for day in days:
        user_resp = api.read_calendar("", day)
        user_offset = parse_offset(user_resp.get("utc_offset", "+00:00"))
        blocks = []

        people = [""]
        for attendee in attendees:
            people.append(attendee)

        for person in people:
            resp = user_resp if person == "" else api.read_calendar(person, day)
            person_offset = parse_offset(resp.get("utc_offset", "+00:00"))
            delta = user_offset - person_offset

            work = resp.get("working_hours", "")
            allowed = []

            if work:
                parts = str(work).split("-")
                if len(parts) == 2:
                    allowed = convert_interval(parse_time(parts[0].strip()),
                                              parse_time(parts[1].strip()),
                                              delta)
            else:
                allowed = [(0, 1440)]

            if not work and not allowed:
                allowed = [(0, 1440)]

            if not allowed:
                blocks.append((0, 1440))
            else:
                allowed = merge_intervals(allowed)
                prev = 0
                for a, b in allowed:
                    if prev < a:
                        blocks.append((prev, a))
                    if b > prev:
                        prev = b
                if prev < 1440:
                    blocks.append((prev, 1440))

            note = str(resp.get("note", ""))
            buffer_minutes = first_number(note) if ("leave" in note.lower() and "minute" in note.lower()) else 0

            day_item = get_day_item(resp, day)
            for ev in day_item.get("events", []):
                if str(ev.get("show_as", "busy")).lower() != "free":
                    ev_parts = convert_interval(parse_time(ev.get("start", "00:00")),
                                                parse_time(ev.get("end", "00:00")),
                                                delta)
                    for a, b in ev_parts:
                        a -= buffer_minutes
                        b += buffer_minutes
                        if b <= 0 or a >= 1440:
                            continue
                        blocks.append((max(0, a), min(1440, b)))

        day_blocks.append(blocks)

    starts = []
    for start_minute in range(first_start, last_start + 1, 15):
        end_minute = start_minute + minutes
        if end_minute > 1440:
            continue
        ok = True
        for blocks in day_blocks:
            for a, b in blocks:
                if start_minute < b and end_minute > a:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            starts.append(fmt_time(start_minute))

    return {"starts": starts}
