        if s[0] == "-":
            sign = -1
        h = int(s[1:3])
        q = int(s[4:6])
        return sign * (h * 60 + q)

    def ceil_quarter(m):
        return ((m + 14) // 15) * 15

    def merge(intervals):
        if len(intervals) == 0:
            return []
        intervals = sorted(intervals)
        out = [intervals[0]]
        for item in intervals[1:]:
            last = out[-1]
            if item[0] <= last[1]:
                if item[1] > last[1]:
                    out[-1] = (last[0], item[1])
            else:
                out.append(item)
        return out

    def overlaps(a1, a2, b1, b2):
        return not (a2 <= b1 or a1 >= b2)

