            wh = cal.get("working_hours", "00:00-24:00")
            ws, we = wh.split("-")
            ws = to_minutes(ws) + shift
            we = to_minutes(we) + shift

            note = cal.get("note", "")
            if "15 minute" in note.lower():
                ws += 15
                we -= 15

