                continue

            events = dayinfo.get("events", [])
            for event in events:
                if event.get("show_as", "busy") == "free":
                    continue
                s = to_minutes(event["start"]) + shift
                e = to_minutes(event["end"]) + shift
                if e <= 0 or s >= 24 * 60:
                    continue
                if s < 0:
                    s = 0
                if e > 24 * 60:
                    e = 24 * 60
                busy.append((s, e))

        if day_end - day_start < minutes:
            valid = set()
        else:
            merged = merge(busy)
            valid = set()
            start = ceil_quarter(day_start)
            last_start = day_end - minutes
            while start <= last_start:
