                ok = True
                for b in merged:
                    if overlaps(start, end, b[0], b[1]):
                        ok = False
                        break
                if ok:
                    valid.add(to_time(start))
                start += 15

        if common is None:
            common = valid
        else:
            common = common.intersection(valid)

        if len(common) == 0:
            return {"starts": []}

    if common is None:
        return {"starts": []}

    return {"starts": sorted(common)}
