    def parse_time(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def parse_offset(text):
        sign = 1
        if text and text[0] == "-":
            sign = -1
            text = text[1:]
        elif text and text[0] == "+":
            text = text[1:]
        parts = text.split(":")
        return sign * (int(parts[0]) * 60 + int(parts[1]))

    def format_time(total):
        h, m = divmod(total, 60)
        return str(h).rjust(2, "0") + ":" + str(m).rjust(2, "0")

    def parse_window(text):
        if not text:
            return 0, 24 * 60
        parts = text.split("-")
        return parse_time(parts[0]), parse_time(parts[1])

    def overlap(a1, a2, b1, b2):
        return a1 < b2 and a2 > b1

    def inside(a1, a2, b1, b2):
        return a1 >= b1 and a2 <= b2

    def uniq(items):
        seen = set()
        out = []
        for item in items:
            if item not in seen:
                seen.add(item)
                out.append(item)
        return out

    if not days:
        return {"starts": []}

    attendees = uniq(attendees)

    day_data = []
    lower = parse_time(earliest) if earliest else 0
    upper = parse_time(latest_end) if latest_end else 24 * 60

    for day in days:
        user_info = api.read_calendar("", day)
        user_days = user_info.get("days", [])
        user_day = user_days[0] if len(user_days) else {"events": [], "working_hours": ""}

        user_offset = parse_offset(user_info["utc_offset"])
        user_work_start, user_work_end = parse_window(user_info.get("working_hours", ""))

        if user_work_start > lower:
            lower = user_work_start
        if user_work_end < upper:
            upper = user_work_end

        people = []
        for person in attendees:
            info = api.read_calendar(person, day)
            days_list = info.get("days", [])
            one_day = days_list[0] if len(days_list) else {"events": [], "working_hours": ""}

            person_offset = parse_offset(info["utc_offset"])
            delta = user_offset - person_offset
            work_start, work_end = parse_window(info.get("working_hours", ""))

            busy = []
            events = one_day.get("events", [])
            for event in events:
                if event.get("show_as") != "free":
                    busy.append((parse_time(event["start"]) + delta,
                                 parse_time(event["end"]) + delta))

            people.append({
                "delta": delta,
                "work_start": work_start + delta,
                "work_end": work_end + delta,
                "busy": busy
            })

        user_busy = []
        for event in user_day.get("events", []):
            if event.get("show_as") != "free":
                user_busy.append((parse_time(event["start"]), parse_time(event["end"])))

        day_data.append({
            "user_work_start": user_work_start,
            "user_work_end": user_work_end,
            "user_busy": user_busy,
            "people": people
        })

    if latest_end:
        latest_bound = parse_time(latest_end)
        if latest_bound < upper:
            upper = latest_bound

    last_start = upper - minutes
    first_start = ((lower + 14) // 15) * 15

    if first_start > last_start:
        return {"starts": []}

    starts = []
    for start in range(first_start, last_start + 1, 15):
        end = start + minutes
        ok = True

        for data in day_data:
            if not inside(start, end, data["user_work_start"], data["user_work_end"]):
                ok = False
                break

            blocked = data["user_busy"]
            for bstart, bend in blocked:
                if overlap(start, end, bstart, bend):
                    ok = False
                    break
            if not ok:
                break

            for person in data["people"]:
                if not inside(start, end, person["work_start"], person["work_end"]):
                    ok = False
                    break
                for bstart, bend in person["busy"]:
                    if overlap(start, end, bstart, bend):
                        ok = False
                        break
                if not ok:
                    break

            if not ok:
                break

        if ok:
            starts.append(format_time(start))

    return {"starts": starts}
