def find_common_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def time_to_minutes(t):
        if not t:
            return 0
        if t == "24:00":
            return 1440
        parts = t.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def minutes_to_time(m):
        return str(m // 60).zfill(2) + ":" + str(m % 60).zfill(2)

    def parse_offset(off):
        if not off:
            return 0
        sign = 1
        if off[0] == "-":
            sign = -1
        hours = int(off[1:3])
        mins = int(off[4:6])
        return sign * (hours * 60 + mins)

    def ceil_quarter(m):
        return ((m + 14) // 15) * 15

    def floor_quarter(m):
        return (m // 15) * 15

    def get_day(data, day):
        dlist = data.get("days", [])
        target = day[:3].lower()
        for d in dlist:
            name = d.get("day", "").lower()
            if name == target or name == day.lower():
                return d
        if len(dlist) > 0:
            return dlist[0]
        return {}

    def collect_person(person, day, user_offset):
        data = api.read_calendar(person, day)
        info = get_day(data, day)
        offset = parse_offset(data.get("utc_offset", ""))
        delta = user_offset - offset

        wh = data.get("working_hours", "")
        if wh:
            parts = wh.split("-")
            wstart = time_to_minutes(parts[0])
            wend = time_to_minutes(parts[1])
            if wend < wstart:
                wend += 1440
            wstart += delta
            wend += delta
        else:
            wstart = 0
            wend = 1440

        busy = []
        events = info.get("events", [])
        for ev in events:
            if ev.get("show_as", "busy") == "free":
                continue
            s = time_to_minutes(ev.get("start", "00:00"))
            e = time_to_minutes(ev.get("end", "00:00"))
            if e < s:
                e += 1440
            s += delta
            e += delta
            busy.append((s, e))

        return wstart, wend, busy

    if len(days) == 0:
        return {"starts": []}

    earliest_min = time_to_minutes(earliest) if earliest else 0
    latest_end_min = time_to_minutes(latest_end) if latest_end else 1440

    common = None

    for day in days:
        user_data = api.read_calendar("", day)
        user_offset = parse_offset(user_data.get("utc_offset", ""))

        day_start = earliest_min
        day_end = latest_end_min
        busy = []

        user_info = get_day(user_data, day)
        user_wh = user_data.get("working_hours", "")
        if user_wh:
            parts = user_wh.split("-")
            wstart = time_to_minutes(parts[0])
            wend = time_to_minutes(parts[1])
            if wend < wstart:
                wend += 1440
            day_start = max(day_start, wstart)
            day_end = min(day_end, wend)

        for ev in user_info.get("events", []):
            if ev.get("show_as", "busy") == "free":
                continue
            s = time_to_minutes(ev.get("start", "00:00"))
            e = time_to_minutes(ev.get("end", "00:00"))
            if e < s:
                e += 1440
            busy.append((s, e))

        for person in attendees:
            wstart, wend, more_busy = collect_person(person, day, user_offset)
            day_start = max(day_start, wstart)
            day_end = min(day_end, wend)
            for interval in more_busy:
                busy.append(interval)

        day_start = max(day_start, 0)
        day_end = min(day_end, 1440)

        starts = set()
        first = ceil_quarter(day_start)
        last = floor_quarter(day_end - minutes)

        if last >= first:
            for start in range(first, last + 1, 15):
                end = start + minutes
                ok = True
                for bs, be in busy:
                    if start < be and end > bs:
                        ok = False
                        break
                if ok:
                    starts.add(start)

        if common is None:
            common = starts
        else:
            common = common.intersection(starts)

        if len(common) == 0:
            break

    result = []
    if common is not None and len(common) > 0:
        for m in sorted(common):
            result.append(minutes_to_time(m))

    return {"starts": result}
