    def ceil_quarter(total):
        q, r = divmod(total, 15)
        if r == 0:
            return q * 15
        return (q + 1) * 15

    def convert_to_user(local_minutes, person_offset, user_offset):
        return local_minutes + user_offset - person_offset

    def day_record(data, day_name):
        items = data.get("days", [])
        if len(items) == 0:
