            return 0
        text = note.lower()
        digits = ""
        for ch in text:
            if "0" <= ch <= "9":
                digits += ch
            elif digits:
                break
        if digits == "":
            return 0
        return int(digits)

    if len(days) == 0:
        return {"starts": []}

    common = None

    for day in days:
        user_data = api.read_calendar("", day)
        user_offset = parse_offset(user_data["utc_offset"])
        user_day = day_record(user_data, day)

