    def toMin(text):
        return int(text[0:2]) * 60 + int(text[3:5])

    def fromMin(value):
        return str(value // 60).zfill(2) + ":" + str(value % 60).zfill(2)

    def parseOffset(text):
        sign = -1 if text[0] == "-" else 1
        return sign * (int(text[1:3]) * 60 + int(text[4:6]))

    def convertRange(startText, endText, personOffset, userOffset):
        start = toMin(startText)
        end = toMin(endText)
        dur = end - start
        if dur <= 0:
            dur += 1440
        if dur <= 0:
            return []
        if dur >= 1440:
            return [[0, 1440]]
        shift = userOffset - personOffset
        s2 = (start + shift) % 1440
        e2 = s2 + dur
        if e2 <= 1440:
            return [[s2, e2]]
        return [[s2, 1440], [0, e2 - 1440]]

    def getItem(data):
        dayList = data.get("days", [])
        if len(dayList) == 0:
            return {"events": [], "working_hours": "00:00-24:00"}
        return dayList[0]

    if len(days) == 0:
        return {"starts": []}

    earliestMin = toMin(earliest) if earliest != "" else 0
    latestMin = toMin(latest_end) if latest_end != "" else 1440
    if latestMin - minutes < earliestMin:
        return {"starts": []}

    common = None

    for day in days:
        people = []

        userData = api.read_calendar("", day)
        userItem = getItem(userData)
        userOffset = parseOffset(userData.get("utc_offset", "+00:00"))

        userWork = []
        userWorkText = userItem.get("working_hours", "")
        if userWorkText != "":
            pieces = userWorkText.split("-")
            if len(pieces) == 2:
                userWork = convertRange(pieces[0], pieces[1], userOffset, userOffset)

        userBusy = []
        for event in userItem.get("events", []):
            if event.get("show_as", "busy") == "free":
                continue
            userBusy.extend(convertRange(event["start"], event["end"], userOffset, userOffset))

        people.append({"work": userWork, "busy": userBusy})

        for person in attendees:
            data = api.read_calendar(person, day)
            item = getItem(data)
            personOffset = parseOffset(data.get("utc_offset", "+00:00"))

            work = []
            workText = item.get("working_hours", "")
            if workText != "":
                pieces = workText.split("-")
                if len(pieces) == 2:
                    work = convertRange(pieces[0], pieces[1], personOffset, userOffset)

            busy = []
            for event in item.get("events", []):
                if event.get("show_as", "busy") == "free":
                    continue
                busy.extend(convertRange(event["start"], event["end"], personOffset, userOffset))

            people.append({"work": work, "busy": busy})

        valid = []
        for start in range(0, 24 * 60, 15):
            if start < earliestMin:
                continue
            end = start + minutes
            if end > latestMin:
                continue
            if end > 24 * 60:
                continue

            ok = True
            for person in people:
                inWork = False
                for win in person["work"]:
                    if start >= win[0] and end <= win[1]:
                        inWork = True
                        break
                if not inWork:
                    ok = False
                    break

                for block in person["busy"]:
                    if not (end <= block[0] or start >= block[1]):
                        ok = False
                        break
                if not ok:
                    break

            if ok:
                valid.append(start)

        if common is None:
            common = valid
        else:
            validSet = set(valid)
            common = [x for x in common if x in validSet]

    if common is None:
        common = []

    return {"starts": [fromMin(x) for x in sorted(common)]}
