def find_common_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parse_time(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def format_time(value):
        value = value % 1440
        return str(value // 60).zfill(2) + ":" + str(value % 60).zfill(2)

    def parse_offset(text):
        sign = -1 if text[0] == "-" else 1
        parts = text[1:].split(":")
        return sign * (int(parts[0]) * 60 + int(parts[1]))

    def ceil_quarter(value):
        rem = value % 15
        if rem == 0:
            return value
        return value + (15 - rem)

    def normalize(parts):
        clean = []
        for a, b in parts:
            if b <= a:
                continue
            if b <= 0 or a >= 1440:
                continue
            if a < 0:
                a = 0
            if b > 1440:
                b = 1440
            if b > a:
                clean.append((a, b))
        clean.sort()
        merged = []
        for a, b in clean:
            if not merged or a > merged[-1][1]:
                merged.append([a, b])
            elif b > merged[-1][1]:
                merged[-1][1] = b
        return [(a, b) for a, b in merged]

    def note_buffer(text):
        low = text.lower()
        if "minutes" not in low or "between" not in low or "meeting" not in low:
            return 0
        num = ""
        got = False
        for ch in low:
            if ch >= "0" and ch <= "9":
                num += ch
                got = True
            elif got:
                break
        if num:
            return int(num)
        return 0

    def get_day_record(data, day):
        items = data.get("days", [])
        for rec in items:
            if rec.get("day") == day:
                return rec
        if items:
            return items[0]
        return {"events": []}

    def fits(info, start, end):
        work_ranges = info["work"]
        blocked = info["blocked"]

        in_work = False
        for a, b in work_ranges:
            if start >= a and end <= b:
                in_work = True
                break
        if not in_work:
            return False

        for a, b in blocked:
            if start < b and end > a:
                return False
        return True

    if minutes < 0 or not days:
        return {"starts": []}

    seen = set()
    attendee_list = []
    for name in attendees:
        if name not in seen:
            seen.add(name)
            attendee_list.append(name)

    if earliest:
        start_bound = ceil_quarter(parse_time(earliest))
    else:
        start_bound = 0

    if start_bound >= 1440:
        return {"starts": []}

    if latest_end:
        end_bound = parse_time(latest_end) - minutes
    else:
        end_bound = 1440 - minutes

    if end_bound >= 1440:
        end_bound = 1439
    end_bound = (end_bound // 15) * 15

    if end_bound < start_bound:
        return {"starts": []}

    common = None

    for day in days:
        user_data = api.read_calendar("", day)
        user_offset = parse_offset(user_data.get("utc_offset", "+00:00"))

        infos = []
        for person in [""] + attendee_list:
            data = user_data if person == "" else api.read_calendar(person, day)
            person_offset = parse_offset(data.get("utc_offset", "+00:00"))
            diff = user_offset - person_offset

            wh = data.get("working_hours", "00:00-24:00")
            if "-" in wh:
                parts = wh.split("-")
                ws = parse_time(parts[0]) + diff
                we = parse_time(parts[1]) + diff
            else:
                ws = 0
                we = 1440
            work = normalize([(ws, we)])

            buf = note_buffer(data.get("note", ""))
            dayrec = get_day_record(data, day)
            blocked_parts = []
            for event in dayrec.get("events", []):
                if event.get("show_as", "busy") == "busy":
                    s = parse_time(event.get("start", "00:00")) + diff - buf
                    e = parse_time(event.get("end", "00:00")) + diff + buf
                    blocked_parts.append((s, e))
            blocked = normalize(blocked_parts)

            infos.append({"work": work, "blocked": blocked})

        day_common = set()
        for start in range(start_bound, end_bound + 1, 15):
            end = start + minutes
            ok = True
            for info in infos:
                if not fits(info, start, end):
                    ok = False
                    break
            if ok:
                day_common.add(start)

        if common is None:
            common = day_common
        else:
            common = common.intersection(day_common)

        if not common:
            return {"starts": []}

    return {"starts": [format_time(x) for x in sorted(common)]}
