def find_common_starts(api, attendees, days, minutes, earliest="", latest_end=""):
    def time_to_minutes(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def minutes_to_time(value):
        return str(value // 60).zfill(2) + ":" + str(value % 60).zfill(2)

    def offset_to_minutes(text):
        parts = text.split(":")
        head = parts[0]
        sign = 1
        if head[0] == "-":
            sign = -1
            head = head[1:]
        elif head[0] == "+":
            head = head[1:]
        return sign * (int(head) * 60 + int(parts[1]))

    def note_buffer(text):
        nums = []
        current = ""
        for ch in text:
            if ch >= "0" and ch <= "9":
                current += ch
            else:
                if current != "":
                    nums.append(int(current))
                    current = ""
        if current != "":
            nums.append(int(current))
        if len(nums) > 0:
            return nums[0]
        return 0

    def day_entry(record, day):
        items = record.get("days", [])
        target = day.lower()[:3]
        for item in items:
            if item.get("day", "").lower()[:3] == target:
                return item
        if len(items) > 0:
            return items[0]
        return {}

    def available(record, day, start, end, user_offset):
        person_offset = offset_to_minutes(record.get("utc_offset", "+00:00"))
        shift = user_offset - person_offset

        work_parts = record.get("working_hours", "00:00-24:00").split("-")
        work_start = time_to_minutes(work_parts[0]) + shift
        work_end = time_to_minutes(work_parts[1]) + shift
        if start < work_start or end > work_end:
            return False

        buffer = note_buffer(record.get("note", ""))
        item = day_entry(record, day)
        events = item.get("events", [])
        for event in events:
            if event.get("show_as", "busy") == "busy":
                ev_start = time_to_minutes(event.get("start", "00:00")) + shift - buffer
                ev_end = time_to_minutes(event.get("end", "00:00")) + shift + buffer
                if start < ev_end and end > ev_start:
                    return False
        return True

    if len(days) == 0:
        return {"starts": []}

    records = {}
    user_record = api.read_calendar("", days[0])
    user_offset = offset_to_minutes(user_record.get("utc_offset", "+00:00"))
    records[("", days[0])] = user_record

    for day in days:
        if day != days[0]:
            records[("", day)] = api.read_calendar("", day)
        for person in attendees:
            records[(person, day)] = api.read_calendar(person, day)

    people = [""]
    for person in attendees:
        people.append(person)

    first = 0
    if earliest != "":
        first = ((time_to_minutes(earliest) + 14) // 15) * 15

    last = 24 * 60 - minutes
    if latest_end != "":
        last = time_to_minutes(latest_end) - minutes

    starts = []
    for start in range(first, last + 1, 15):
        end = start + minutes
        ok = True
        for day in days:
            for person in people:
                record = records[(person, day)]
                if not available(record, day, start, end, user_offset):
                    ok = False
                    break
            if not ok:
                break
        if ok:
            starts.append(minutes_to_time(start))

    return {"starts": starts}
