def find_common_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    """Find every start time that works for the user and all the listed attendees on every one of the given days, for a meeting of the given length, so it can be held at the same time each day. days are mon to fri; earliest is the first allowed start and latest_end the time the meeting must end by, both HH:MM or empty. Returns the common starts, earliest first."""
    def time_to_min(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def min_to_time(total):
        return str(total // 60).rjust(2, "0") + ":" + str(total % 60).rjust(2, "0")

    def offset_to_min(text):
        sign = 1
        if text and text[0] == "-":
            sign = -1
            text = text[1:]
        elif text and text[0] == "+":
            text = text[1:]
        return sign * time_to_min(text)

    def shift_min(text, delta):
        return time_to_min(text) + delta

    def calendar_info(cal, delta):
        wh = cal.get("working_hours", "00:00-00:00").split("-")
        ws = shift_min(wh[0], delta)
        we = shift_min(wh[1], delta)
        busy = []
        day_items = cal.get("days", [])
        if len(day_items) != 0:
            events = day_items[0].get("events", [])
            for event in events:
                if event.get("show_as") == "busy":
                    bs = shift_min(event.get("start", "00:00"), delta)
                    be = shift_min(event.get("end", "00:00"), delta)
                    busy.append((bs, be))
        return ws, we, busy

    if len(days) == 0:
        return {"starts": []}

    earliest_min = None
    latest_min = None
    if earliest != "":
        earliest_min = time_to_min(earliest)
    if latest_end != "":
        latest_min = time_to_min(latest_end)

    people = []
    for person in attendees:
        if person != "" and person not in people:
            people.append(person)

    common = None

    for day in days:
        user_cal = api.read_calendar("", day)
        user_offset = offset_to_min(user_cal.get("utc_offset", "+00:00"))

        day_data = []
        day_data.append(calendar_info(user_cal, 0))

        for person in people:
            cal = api.read_calendar(person, day)
            person_offset = offset_to_min(cal.get("utc_offset", "+00:00"))
            delta = user_offset - person_offset
            day_data.append(calendar_info(cal, delta))

        valid = []
        for start in range(0, 24 * 60, 15):
            if earliest_min is not None and start < earliest_min:
                continue
            if latest_min is not None and start + minutes > latest_min:
                continue

            ok = True
            for ws, we, busy in day_data:
                if start < ws or start + minutes > we:
                    ok = False
                    break
                for bs, be in busy:
                    if not (start + minutes <= bs or start >= be):
                        ok = False
                        break
                if not ok:
                    break

            if ok:
                valid.append(start)

        if common is None:
            common = set(valid)
        else:
            common = common.intersection(valid)

    if common is None:
        common = set()

    starts = []
    for start in sorted(common):
        starts.append(min_to_time(start))

    return {"starts": starts}
